<?php
namespace App\Http\Controllers; use App\Models\{Empleado,TrainingReinforcement}; use App\Services\TrainingSessionService; use Illuminate\Http\Request;
class TrainingReinforcementController extends Controller{public function index(){ $company=auth()->user()->company_id;$reinforcements=TrainingReinforcement::where('company_id',$company)->with(['employee','attempt.evaluation.topic'])->get();$employees=Empleado::where('company_id',$company)->active()->get();return view('training.reinforcements.index',compact('reinforcements','employees'));}public function schedule(TrainingReinforcement$reinforcement,Request$r,TrainingSessionService$s){abort_unless($reinforcement->company_id===$r->user()->company_id,403);$d=$r->validate(['scheduled_start_at'=>'required|date','scheduled_end_at'=>'required|date|after:scheduled_start_at','instructor_employee_id'=>'required|exists:empleados,id','location'=>'nullable|string|max:255']);$topic=$reinforcement->attempt->evaluation->topic;$session=$s->create(['training_topic_id'=>$topic->id,'title'=>'Refuerzo: '.$topic->name,'description'=>'Sesión de refuerzo administrativamente programada.','training_type'=>'training','session_purpose'=>'reinforcement','scheduled_start_at'=>$d['scheduled_start_at'],'scheduled_end_at'=>$d['scheduled_end_at'],'planned_duration_minutes'=>max(1,\Carbon\Carbon::parse($d['scheduled_start_at'])->diffInMinutes(\Carbon\Carbon::parse($d['scheduled_end_at']))),'modality'=>'presential','location'=>$d['location']??null,'instructor_type'=>'internal','instructor_employee_id'=>$d['instructor_employee_id'],'audience_type'=>'specific_employees','audience_description'=>'Trabajador con refuerzo pendiente','specific_employee_ids'=>[$reinforcement->employee_id],'requires_attendance'=>true,'requires_signature'=>true,'requires_material'=>false,'requires_execution_report'=>true,'extraordinary_reason'=>'Refuerzo requerido por evaluación no aprobada','extraordinary_origin'=>'evaluation'], $r->user()->company_id,$r->user()->id);$s->schedule($session,$r->user()->id);$reinforcement->update(['reinforcement_session_id'=>$session->id,'status'=>'scheduled','updated_by'=>$r->user()->id]);return redirect()->route('training.sessions.show',$session)->with('success','Refuerzo programado mediante una sesión CAP-2.');}}
